CREATE TABLE IF NOT EXISTS case_preflights (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL, description_hash text NOT NULL, verdict text NOT NULL, result jsonb NOT NULL DEFAULT '{}'::jsonb, file_hashes jsonb NOT NULL DEFAULT '[]'::jsonb, expires_at timestamptz NOT NULL, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS case_preflights_user_idx ON case_preflights(user_id,created_at DESC);

CREATE TABLE IF NOT EXISTS dispute_routes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), issue_type text NOT NULL, payment_method text, provider_key text, level integer NOT NULL, organization text NOT NULL, route_type text NOT NULL, channel text NOT NULL, destination text NOT NULL, official_url text, prerequisite jsonb NOT NULL DEFAULT '{}'::jsonb, required_documents jsonb NOT NULL DEFAULT '[]'::jsonb, response_expectation_hours integer, active boolean NOT NULL DEFAULT true, source_url text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS dispute_routes_match_idx ON dispute_routes(issue_type,payment_method,provider_key,level);

CREATE TABLE IF NOT EXISTS dispute_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL, user_id text NOT NULL, route_id uuid NOT NULL, level integer NOT NULL, organization text NOT NULL, channel text NOT NULL, destination text NOT NULL, status text NOT NULL DEFAULT 'PREPARED', external_reference text, subject text, body text, package_json jsonb NOT NULL DEFAULT '{}'::jsonb, sent_at timestamptz, next_follow_up_at timestamptz, last_response_at timestamptz, closed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS dispute_attempts_case_idx ON dispute_attempts(case_id,level,created_at DESC);

CREATE TABLE IF NOT EXISTS dispute_requirements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL, user_id text NOT NULL, attempt_id uuid, requirement text NOT NULL, reason text, status text NOT NULL DEFAULT 'REQUESTED', response_evidence_id uuid, created_at timestamptz NOT NULL DEFAULT now(), satisfied_at timestamptz);
CREATE INDEX IF NOT EXISTS dispute_requirements_case_idx ON dispute_requirements(case_id,status,created_at DESC);

CREATE TABLE IF NOT EXISTS dispute_responses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL, user_id text NOT NULL, attempt_id uuid, source text NOT NULL, channel text, external_reference text, raw_text text NOT NULL, structured_response jsonb NOT NULL DEFAULT '{}'::jsonb, interpreted_state text NOT NULL DEFAULT 'UNCLASSIFIED', next_action text, confidence numeric, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS dispute_responses_case_idx ON dispute_responses(case_id,created_at DESC);

CREATE TABLE IF NOT EXISTS dispute_state (case_id uuid PRIMARY KEY, user_id text NOT NULL, phase text NOT NULL DEFAULT 'VERIFYING', current_level integer NOT NULL DEFAULT 0, current_attempt_id uuid, waiting_for_user boolean NOT NULL DEFAULT false, next_action text, next_action_at timestamptz, last_meaningful_update_at timestamptz NOT NULL DEFAULT now(), resolution_status text NOT NULL DEFAULT 'OPEN', updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS dispute_state_due_idx ON dispute_state(next_action_at,resolution_status);

INSERT INTO dispute_routes (issue_type,payment_method,level,organization,route_type,channel,destination,official_url,prerequisite,required_documents,response_expectation_hours,source_url) VALUES ('payment_failed_deducted','UPI',1,'Payer bank / UPI PSP','FIRST_LINE','GUIDED','UPI app → transaction → Raise complaint','https://www.npci.org.in/what-we-do/upi/faqs','{"must_have":["transaction reference or UTR"]}'::jsonb,'["payment screenshot","UTR/RRN","bank debit proof"]'::jsonb,120,'https://www.npci.org.in/what-we-do/upi/faqs') ON CONFLICT DO NOTHING;
